\label{lem:two:S}
If $M = 2$, then
\begin{align}
\widehat{\mathcal{S}} = \left \{ S \in \mathcal{S}: \quad \begin{aligned} &\textnormal{there exists }i_1 \in S_1 \setminus S_2 \textnormal{ and }  i_2 \in S_2 \setminus S_1 \textnormal{ such that}\\
&S =  \left(S_1 \cap S_2 \right) \cup \left \{j \in  S_1 \setminus S_2: j \ge i_1 \right \}  \cup \left \{j \in  S_2 \setminus S_1: j \ge i_2 \right \}\end{aligned} \right \}. \label{line:S_two}
\end{align}

\label{prop:reform_wc}
 For each  $S \in \mathcal{S}$, $\min_{\lambda \in \mathcal{U}} \mathscr{R}^\lambda(S)$ is equal to the optimal objective value of the following linear optimization problem:
\begin{equation} 
\label{prob:robust_simplified}
 \begin{aligned}
& \; \underset{\lambda, \epsilon}{\textnormal{minimize}} && \sum_{(i_1,\ldots,i_M) \in \mathcal{L}} \rho_{i_1 \cdots i_M}(S) \lambda_{i_1\cdots i_M}\\
&\textnormal{subject to}&&  \sum_{(i_1,\ldots,i_M) \in \mathcal{L}: \; i_m = i} \lambda_{i_1 \cdots i_M} - \epsilon_{m,i}= v_{m,i} \quad \forall m \in \mathcal{M}, \; i \in S_m\\
&&& \sum_{(i_1,\ldots,i_M) \in \mathcal{L}} \lambda_{i_1 \cdots i_M} = 1 \\
&&& \| \epsilon \| \le \eta\\
&&& \lambda_{i_1 \cdots i_M} \ge 0 \quad \forall (i_1,\ldots,i_M) \in \mathcal{L}.
\end{aligned}
\end{equation}

\label{lem:two:L}
If $M = 2$, then
$\mathcal{L} = \left((S_1 \setminus S_2) \times S_2 \right) \cup \left( S_1 \times (S_2 \setminus S_1) \right) \cup  \left\{(i,i): i \in S_1 \cap S_2 \right \}$.

\label{lem:reform_of_L} 
If Assumption~\ref{ass:nested} holds, then
$$\mathcal{L} = \left \{(i_1,\ldots,i_M) \in S_1 \times \cdots \times S_M:\textnormal{ for each }m \in \{1,\ldots,M-1\},  \;  i_{m+1} \in \{i_m \} \cup \mathcal{B}_{m+1}  \right \}.$$

\label{lem:rho_m}
If Assumption~\ref{ass:nested} holds and the assortment $S  \subseteq \mathcal{N}_0$ satisfies $S \cap S_1 \neq \emptyset$,\thanks{The condition that $S \cap S_1 \neq \emptyset$ in Lemma~\ref{lem:rho_m} is satisfied, for example,  when $S, S_1 \in \mathcal{S}$.} then the following equality holds for each tuple $(i_1,\ldots,i_M) \in \mathcal{L}$ and $m \in \mathcal{M}$:
\begin{align} \label{defn:rho_m}
\rho_{i_1 \cdots i_M}(S \cap S_m) &= \begin{cases}
r_{i_m},&\textnormal{if } i_m \in S, \\
\min \limits_{i \in \mathcal{B}_m \cap S} r_i, &\textnormal{if }   i_m \notin S \textnormal{ and } m = 1,\\
\min \left \{ \min \limits_{i \in \mathcal{B}_m \cap S} r_i ,\; \rho_{i_1 \cdots i_M} \left(S \cap S_{m-1}  \right) \right \}, &\textnormal{if }  i_m \notin S \textnormal{ and }  m \ge 2. 
\end{cases}
\end{align}

\label{lem:reachable_v2}
Let $(i_1,\ldots,i_M) \in \mathcal{L}$, $S \in \mathcal{S}$, and $i \in S$. Then, there exists a ranking $\sigma \in \cap_{m \in \mathcal{M}} \mathcal{D}_{i_m}(S_m)$  that satisfies  $i = \mathop{\SFrm arg\,min}_{j \in S} \sigma(j)$                                
if and only if $j \nprec_{i_1 \cdots i_M} i$ for all $j \in S$.

\label{prop:cost_reform}
For all $S \in \mathcal{S}$ and $(i_1,\ldots,i_M) \in \mathcal{L}$, 
$\rho_{i_1 \cdots i_M}(S) = \min_{i \in S \cap \mathcal{I}_{i_1 \cdots i_M}(S)} r_i.$

\label{claim:add_one}
For all $S \in \mathcal{S}$, $(i_1,\ldots,i_M) \in \mathcal{L}$, and $i \notin S$,
\begin{align*}
&\rho_{i_1 \cdots i_M}(S \cup \{i\}) = \begin{cases}
\rho_{i_1 \cdots i_M}(S),&\textnormal{if } i \notin \mathcal{I}_{i_1 \cdots i_M}(S),\\
\min \left \{ \min \limits_{j \in S \cap \mathcal{I}_{i_1 \cdots i_M}(S) \cap \left\{ j' \in \mathcal{N}_0: i \nprec_{i_1 \cdots i_M} j' \right\}} r_j, r_i \right \}, &\textnormal{if } i \in \mathcal{I}_{i_1 \cdots i_M}(S).\\
\end{cases}
\end{align*}

\begin{enumerate}
\item Initialize the vertex set $\mathscr{V} \leftarrow \emptyset$ and edge set $\mathscr{E} \leftarrow \emptyset$. 
\item For each product $i \in \mathcal{N}_0$: \label{step:iterative_of_i}                                        
\begin{enumerate}
\item Update $\mathscr{V} \leftarrow \mathscr{V} \cup \{i \}$. 
\item Construct the set $\mathcal{M}_i$ of past assortments which offered product $i$. 
\end{enumerate}
\item For each pair of products $(i^*,i) \in \mathcal{N}_0 \times \mathcal{N}_0$:
\begin{enumerate}
\item If $r_{i^*} < r_{i}$ and $\mathcal{M}_{i^*} \subseteq \mathcal{M}_i$:
\begin{enumerate}
\item Update $\mathscr{E} \leftarrow \mathscr{E} \cup \{(i^*,i) \}$
\end{enumerate}
\end{enumerate}
\item Output $\mathscr{G} \equiv (\mathscr{V},\mathscr{E})$ and terminate. 
\end{enumerate}
\end{minipage}}
\end{center}
\caption{A procedure for constructing the directed acyclic graph $\mathscr{G}$.} \label{alg:construct_G}
\end{algorithm}

\begin{enumerate}
\item Construct the directed acyclic graph $\mathscr{G} \leftarrow \textsc{Construct-${\mathscr{G}}(\mathscr{M},r)$}$.  \label{step:construct_S:1}
\item Compute the collection of assortments $\widehat{\mathcal{S}} \leftarrow \textsc{RecursiveStep$(\mathscr{G})$}$.  \label{step:construct_S:2}
\item For each $S \in \widehat{\mathcal{S}}$:  \label{step:construct_S:3}
\begin{enumerate}
\item If $0 \notin S$:
\begin{enumerate}
\item Update $\widehat{\mathcal{S}} \leftarrow \widehat{\mathcal{S}} \setminus \{ S \}$. 
\end{enumerate}
\end{enumerate}
\item Output $\widehat{\mathcal{S}}$ and terminate. 
\end{enumerate}
\vspace{1em}
\end{minipage}}

\begin{enumerate}
\item If $\mathscr{V} = \emptyset$:
\begin{enumerate}
\item Output the collection $\mathscr{A} \equiv\{ \emptyset \}$ and terminate. 
\end{enumerate}
\item Otherwise:                                           
\begin{enumerate}

\label{claim:appx:idk_2}
Let  $\mathscr{G} \equiv (\mathscr{V},\mathscr{E})$ be a directed acyclic graph that is a transitive closure. For notational convenience, let  $\mathscr{E}_i$ denote the set of incoming and outgoing edges from each vertex $i \in \mathscr{V}$. For each vertex $i \in \mathscr{V}$,              
\begin{align}
  &\left \{S \subseteq \mathscr{V} \setminus \{i \}:  \textnormal{ if $k \in S$ and $(k,j) \in \mathscr{E}$, then $j \in S$} \right\} \notag \\
        & = \left \{ S \subseteq \mathscr{V} \setminus (\{ i \} \cup \{\ell: (\ell,i) \in \mathscr{E} \}): \textnormal{if } k \in  S  \textnormal{ and } (k,j) \in \mathscr{E} \setminus \left( \mathscr{E}_i \cup \bigcup_{\ell: (\ell,i) \in \mathscr{E}} \mathscr{E}_\ell \right), \textnormal{ then } j \in S \right \}. \label{line:remove_i_from_set}
\end{align}

\label{claim:appx:idk_3}
Let  $\mathscr{G} \equiv (\mathscr{V},\mathscr{E})$ be a directed acyclic graph that is a transitive closure. For notational convenience, let  $\mathscr{E}_i$ denote the set of incoming and outgoing edges from each vertex $i \in \mathscr{V}$. For each vertex $i \in \mathscr{V}$, 
\begin{align}
  &\left \{S \subseteq \mathscr{V}: \left[ i \in S \right] \textnormal{ and } \left[  \textnormal{if $k \in S$ and $(k,j) \in \mathscr{E}$, then $j \in S$} \right] \right\} \notag \\

        & = \left \{ \begin{aligned}
        &S' \cup \{i \} \cup \left\{ \ell: (i,\ell) \in \mathscr{E} \right \} :\\
        &\quad S' \in \left \{ S  \subseteq \mathscr{V} \setminus \left( \{i \} \cup \left\{ \ell: (i,\ell) \in \mathscr{E} \right \}  \right):  \textnormal{if } k \in  S  \textnormal{ and } (k,j) \in \mathscr{E} \setminus \left( \mathscr{E}_i \cup \bigcup_{\ell: (i,\ell) \in \mathscr{E}} \mathscr{E}_\ell \right), \textnormal{ then } j \in S \right \} \end{aligned} \right \}.\label{line:add_i_to_set_goofy}
\end{align}

\label{lem:singleton}
The system~\eqref{line:system_feas} is nonempty and has a unique solution $\lambda$ which satisfies the following equality for each $(i_1,\ldots,i_n) \in \mathcal{L}$:








\begin{align}
\lambda_{i_1 \cdots i_n} &= \begin{cases}
\frac{1}{n},&\textnormal{if there exists }  j \in \bar{S}\setminus \{0,n\} \textnormal{ such that } (i_1,\ldots,i_n) =  \left(\text{\b{$i$}}^j_1,\ldots,\text{\b{$i$}}^j_n \right),\\
\frac{1}{n},&\textnormal{if there exists } j \in \mathcal{N} \setminus \bar{S} \textnormal{ such that }(i_1,\ldots,i_n) =  \left(\bar{i}^j_1,\ldots,\bar{i}^j_n \right) ,\\
\frac{1}{n},&\textnormal{if }  (i_{1}, \ldots, i_n) = (n,\ldots,n),\\
0,&\textnormal{otherwise}.
\end{cases} \label{line:singleton:defn_lambda}
\end{align}

\begin{enumerate}
\item Construct the directed acyclic graph $\mathcal{G}_{i_1 \cdots i_M}$.                                                             
\label{step:construct_rho:1}
\item For each past assortment $m \in  \mathcal{M}$:  \label{step:construct_rho:2}
\begin{enumerate}
\item If $i_m \in S$:                                                                                                      
\begin{enumerate}
\item Mark each unmarked vertex in $\mathcal{G}_{i_1 \cdots i_M}$ that has a directed path to vertex $i_m$. 
\end{enumerate}
\end{enumerate}
\item Output the minimum $r_i$ among all unmarked vertices $i$ in $\mathcal{G}_{i_1 \cdots i_M}$ and terminate.  \label{step:construct_rho:3}
\end{enumerate}
\vspace{1em}
\end{minipage}}

\label{lem:simplified_to_compact}
Let Assumption~\ref{ass:nested} hold, let $S \subseteq \mathcal{N}_0$ satisfy $S \cap S_1 \neq \emptyset$, and let $(\lambda,\epsilon)$ be a  feasible solution for the linear optimization problem~\eqref{prob:robust_simplified}. For each vertex $(m,i,\kappa) \in \mathfrak{V}$, let 
\begin{align*}
 g_{m,i,\kappa} &\triangleq \sum_{(i_1,\ldots,i_M) \in \mathcal{L}: \; i_m = i,  \rho_{i_1 \cdots i_M}(S \cap S_m) = \kappa} \lambda_{i_1 \cdots i_M},
 \end{align*}
 and for each directed edge $((m,i,\kappa),(m+1,i',\kappa')) \in \mathfrak{E}$, let 
 \begin{align*}
f_{m,i,\kappa,i',\kappa'} &\triangleq \sum_{(i_1,\ldots,i_M) \in \mathcal{L}: \; i_m = i, \rho_{i_1 \cdots i_M}(S \cap S_m) = \kappa, i_{m+1} = i', \rho_{i_1 \cdots i_M}(S \cap S_{m+1}) = \kappa' } \lambda_{i_1 \cdots i_M}. 
\end{align*}
Then $(f,g,\epsilon)$ is a feasible solution for the linear optimization problem~\eqref{prob:lp_reform_nested}, and the objective value associated with $(f,g,\epsilon)$ in the  linear optimization problem~\eqref{prob:lp_reform_nested} is equal to the objective value associated with $(\lambda,\epsilon)$ in the  linear optimization problem~\eqref{prob:robust_simplified}.

\label{lem:compact_to_bound}

Let Assumption~\ref{ass:nested} hold, let  $S \subseteq \mathcal{N}_0$ satisfy $S \cap S_1 \neq \emptyset$, and let $(f,g,\epsilon)$ satisfy the following constraints:
\begin{align*}
&&& \sum_{\kappa: (m,i,\kappa) \in {\mathfrak{V}}}  g_{m,i,\kappa}  - \epsilon_{m,i}= v_{m,i} && \forall m \in \mathcal{M}, \; i \in S_m \\
&&& \sum_{i',\kappa': ((m,i,\kappa),(m+1,i',\kappa')) \in {\mathfrak{E}}} f_{m,i,\kappa,i',\kappa'}  = g_{m,i,\kappa} && \forall (m,i,\kappa) \in {\mathfrak{V}}: m \in \{1,\ldots,M-1\} \\
&&& \sum_{i',\kappa': ((m-1,i',\kappa'),(m,i,\kappa)) \in {\mathfrak{E}}} f_{m-1,i',\kappa',i,\kappa}  = g_{m,i,\kappa} && \forall (m,i,\kappa) \in {\mathfrak{V}}: m \in \{2,\ldots,M\}\\
&&& \| \epsilon \| \le \eta \\
&&& \sum_{i,\kappa: (M,i,\kappa) \in \mathfrak{V}} g_{M,i,\kappa} = 1 \\
 &&& f_{m,i,\kappa,i',\kappa'} \ge 0 && \forall ((m,i,\kappa),(m+1,i',\kappa')) \in {\mathfrak{E}}  \\
&&& g_{m,i,\kappa} \ge 0 && \forall (m,i,\kappa) \in {\mathfrak{V}}.
\end{align*}
Then there exists a vector $\lambda$ such that $(\lambda,\epsilon)$ is a feasible solution for the linear optimization problem~\eqref{prob:lp_reform_nested} and 
\begin{align*}
\sum_{(i_1,\ldots,i_M) \in \mathcal{L}} \rho_{i_1 \cdots i_M}(S) \lambda_{i_1 \cdots i_M} \le \sum_{i,\kappa: (M,i,\kappa) \in \mathfrak{V}} \kappa g_{m,i,\kappa} + \sum_{(m,i,\kappa) \in \mathfrak{N}(S)} r_n g_{m,i,\kappa}. 
\end{align*}

\label{claim:lp_reform_nested:objective}
Consider any assortment $S \in \mathcal{S}$, and let $\mathfrak{M}(S) \in \mathbb{R}^{{\mathfrak{V}}}$ be any vector that satisfies the inequality $\mathfrak{M}_{m,i,\kappa}(S) \ge r_n$ for all $(m,i,\kappa) \in \mathfrak{N}(S)$ and satisfies the equality $\mathfrak{M}_{m,i,\kappa}(S) = 0$ for all $(m,i,\kappa) \in {\mathfrak{V}} \setminus \mathfrak{N}(S)$. Then the optimal objective value of the linear optimization problem~\eqref{prob:lp_reform_nested} is equal to the optimal objective value of the following linear optimization problem: 
 \begin{equation} \label{prob:nested:compact:objective}

\begin{aligned}
& \; \underset{f, g,\epsilon}{\textnormal{minimize}} && \sum_{i,\kappa: (M,i,\kappa) \in {\mathfrak{V}}} \kappa  g_{M,i,\kappa} + \sum_{(m,i,\kappa) \in {\mathfrak{V}}} \mathfrak{M}_{m,i,\kappa}(S) g_{m,i,\kappa}  \\
&\textnormal{subject to}&& \sum_{\kappa: (m,i,\kappa) \in {\mathfrak{V}}}  g_{m,i,\kappa}  - \epsilon_{m,i}= v_{m,i} && \forall m \in \mathcal{M}, \; i \in S_m \\
&&& \sum_{i',\kappa': ((m,i,\kappa),(m+1,i',\kappa')) \in {\mathfrak{E}}} f_{m,i,\kappa,i',\kappa'}  = g_{m,i,\kappa} && \forall (m,i,\kappa) \in {\mathfrak{V}}: m \in \{1,\ldots,M-1\} \\
&&& \sum_{i',\kappa': ((m-1,i',\kappa'),(m,i,\kappa)) \in {\mathfrak{E}}} f_{m-1,i',\kappa',i,\kappa}  = g_{m,i,\kappa} && \forall (m,i,\kappa) \in {\mathfrak{V}}: m \in \{2,\ldots,M\}\\
&&& \sum_{i,\kappa: (M,i,\kappa) \in \mathfrak{V}} g_{M,i,\kappa} = 1 \\
&&& \| \epsilon \| \le \eta \\
 &&& f_{m,i,\kappa,i',\kappa'} \ge 0 && \forall ((m,i,\kappa),(m+1,i',\kappa')) \in {\mathfrak{E}}  \\
&&& g_{m,i,\kappa} \ge 0 && \forall (m,i,\kappa) \in {\mathfrak{V}}.
\end{aligned} 

\end{equation}

\label{prop:reform_wc:optimistic}
 For each  $S \in \mathcal{S}$, $\max_{\lambda \in \mathcal{U}} \mathscr{R}^\lambda(S)$ is equal to the optimal objective value of the following linear optimization problem:
\begin{equation} 
\label{prob:optimistic_simplified}
 \begin{aligned}
& \; \underset{\lambda, \epsilon}{\textnormal{maximize}} && \sum_{(i_1,\ldots,i_M) \in \mathcal{L}} \xi_{i_1 \cdots i_M}(S) \lambda_{i_1\cdots i_M}\\
&\textnormal{subject to}&&  \sum_{(i_1,\ldots,i_M) \in \mathcal{L}: \; i_m = i} \lambda_{i_1 \cdots i_M} - \epsilon_{m,i}= v_{m,i} \quad \forall m \in \mathcal{M}, \; i \in S_m\\
&&& \sum_{(i_1,\ldots,i_M) \in \mathcal{L}} \lambda_{i_1 \cdots i_M} = 1 \\
&&& \| \epsilon \| \le \eta\\
&&& \lambda_{i_1 \cdots i_M} \ge 0 \quad \forall (i_1,\ldots,i_M) \in \mathcal{L}.
\end{aligned}
\end{equation}

\label{prop:cost_reform:optimistic}
For all $S \in \mathcal{S}$ and $(i_1,\ldots,i_M) \in \mathcal{L}$, 
$\xi_{i_1 \cdots i_M}(S) = \max_{i \in S \cap \mathcal{I}_{i_1 \cdots i_M}(S)} r_i.$

\label{claim:add_one:optimistic}
For all $S \in \mathcal{S}$, $(i_1,\ldots,i_M) \in \mathcal{L}$, and $i \notin S$,
\begin{align*}
&\xi_{i_1 \cdots i_M}(S \cup \{i\}) = \begin{cases}
\xi_{i_1 \cdots i_M}(S),&\textnormal{if } i \notin \mathcal{I}_{i_1 \cdots i_M}(S),\\
\max \left \{ \max \limits_{j \in S \cap \mathcal{I}_{i_1 \cdots i_M}(S) \cap \left\{ j' \in \mathcal{N}_0: i \nprec_{i_1 \cdots i_M} j' \right\}} r_j, r_{i} \right \}, &\textnormal{if } i \in \mathcal{I}_{i_1 \cdots i_M}(S).
\end{cases}
\end{align*}

\begin{enumerate}
\item Initialize the vertex set $\mathscr{V}^{\textnormal{OO}} \leftarrow \emptyset$ and edge set $\mathscr{E}^{\textnormal{OO}} \leftarrow \emptyset$. 
\item For each product $i \in \mathcal{N}^{\textnormal{OO}}$: \label{step:iterative_of_i:optimistic}
\begin{enumerate}
\item Update $\mathscr{V}^{\textnormal{OO}} \leftarrow \mathscr{V}^{\textnormal{OO}} \cup \{i \}$. 
\item Construct the set $\mathcal{M}_i$ of past assortments which offered product $i$. 
\end{enumerate}
\item For each pair of products $(i^*,i) \in \mathcal{N} \times \mathcal{N} $:
\begin{enumerate}
\item If $r_{i^*} > r_{i}$ and $\mathcal{M}_{i^*} \subseteq \mathcal{M}_i$:
\begin{enumerate}
\item Update $\mathscr{E}^{\textnormal{OO}} \leftarrow \mathscr{E}^{\textnormal{OO}} \cup \{(i^*,i) \}$
\end{enumerate}
\end{enumerate}
\item Output $\mathscr{G}^{\textnormal{OO}} \equiv (\mathscr{V}^{\textnormal{OO}},\mathscr{E}^{\textnormal{OO}})$ and terminate. 
\end{enumerate}
\end{minipage}}
\end{center}
\caption{A procedure for constructing the directed acyclic graph $\mathscr{G}^{\textnormal{OO}}$.} \label{alg:construct_G:optimistic}
\end{algorithm}

\begin{enumerate}
\item Construct the directed acyclic graph $\mathscr{G}^{\textnormal{OO}} \leftarrow \textsc{Construct-${\mathscr{G}}^{\textnormal{OO}}(\mathscr{M},r)$}$.  \label{step:construct_S:1:optimistic}
\item Compute the collection of assortments $\widehat{\mathcal{S}}^{\textnormal{OO}} \leftarrow \textsc{RecursiveStep-OO$(\mathscr{G}^{\textnormal{OO}})$}$.  \label{step:construct_S:2:optimistic}
\item Output $\{ S \cup \{0\}: S \in \widehat{\mathcal{S}}^{\textnormal{OO}}\}$ and terminate. 
\end{enumerate}
\vspace{1em}
\end{minipage}}

\begin{enumerate}
\item If $\mathscr{V}^{\textnormal{OO}} = \emptyset$:
\begin{enumerate}
\item Output the collection $\mathscr{A}^{\textnormal{OO}} \equiv\{ \emptyset \}$ and terminate. 
\end{enumerate}
\item Otherwise:                                           
\begin{enumerate}

\label{claim:appx:idk_2:optimistic}
Let  $\mathscr{G}^{\textnormal{OO}} \equiv (\mathscr{V}^{\textnormal{OO}},\mathscr{E}^{\textnormal{OO}})$ be a directed acyclic graph that is a transitive closure. For notational convenience, let  $\mathscr{E}_i^{\textnormal{OO}}$ denote the set of incoming and outgoing edges from each vertex $i \in \mathscr{V}^{\textnormal{OO}}$. For each vertex $i \in \mathscr{V}^{\textnormal{OO}}$,              
\begin{align*}
  &\left \{S \subseteq \mathscr{V}^{\textnormal{OO}} \setminus \{i \}:  \textnormal{ if $k \in S$ and $(k,j) \in \mathscr{E}^{\textnormal{OO}}$, then $j \notin S$} \right\} \notag \\
        & = \left \{ S \subseteq \mathscr{V}^{\textnormal{OO}} \setminus \{ i \}: \textnormal{if } k \in  S  \textnormal{ and } (k,j) \in \mathscr{E}^{\textnormal{OO}} \setminus \mathscr{E}_i^{\textnormal{OO}}, \textnormal{ then } j \notin S \right \}.                                           
\end{align*}

\label{claim:appx:idk_3:optimistic}
Let  $\mathscr{G}^{\textnormal{OO}} \equiv (\mathscr{V}^{\textnormal{OO}},\mathscr{E}^{\textnormal{OO}})$ be a directed acyclic graph that is a transitive closure. For notational convenience, let  $\mathscr{E}_i^{\textnormal{OO}}$ denote the set of incoming and outgoing edges from each vertex $i \in \mathscr{V}^{\textnormal{OO}}$. For each vertex $i \in \mathscr{V}^{\textnormal{OO}}$,
\begin{align*}
  &\left \{S \subseteq \mathscr{V}^{\textnormal{OO}}: \left[ i \in S \right] \textnormal{ and } \left[  \textnormal{if $k \in S$ and $(k,j) \in \mathscr{E}^{\textnormal{OO}}$, then $j \notin S$} \right] \right\} \notag \\
        & = \left \{ \begin{aligned}
        &S' \cup \{i \}:\\
        &\quad S' \in \left \{ \begin{aligned}
        &S  \subseteq \mathscr{V}^{\textnormal{OO}} \setminus \left( \{i \} \cup \left\{ \ell: (i,\ell) \in \mathscr{E}^{\textnormal{OO}} \right \}  \cup \left\{ \ell: (\ell,i) \in \mathscr{E}^{\textnormal{OO}} \right \} \right): \\
        &\quad  \textnormal{if } k \in  S  \textnormal{ and } (k,j) \in \mathscr{E}^{\textnormal{OO}} \setminus \left( \mathscr{E}_i^{\textnormal{OO}}  \cup \bigcup_{\ell: (i,\ell) \in \mathscr{E}^{\textnormal{OO}} } \mathscr{E}_\ell^{\textnormal{OO}}  \cup \bigcup_{\ell: (\ell,i) \in \mathscr{E}^{\textnormal{OO}} } \mathscr{E}_\ell^{\textnormal{OO}} \right), \textnormal{ then } j \in S \end{aligned}  \right \} \end{aligned} \right \}.                                           
\end{align*}

\label{claim:lp_reform_nested:reverse}
For each  $S \subseteq \mathcal{N}_0$ that satisfies $S \cap S_1 \neq \emptyset$, $\max_{\lambda \in \mathcal{U}} \mathscr{R}^\lambda(S)$ is equal to the optimal objective value of the following linear optimization problem:
